stripes = [lock() for _ in range(N)]          # N = small multiple of cores

def with_key(key, fn):
    i = stable_hash(key) % N                  # deterministic: equal key -> same stripe
    stripes[i].acquire()
    try:
        return fn()
    finally:
        stripes[i].release()

